CREATE TABLE ibexa_content_trash (node_id INT DEFAULT 0 NOT NULL, contentobject_id INT DEFAULT NULL, contentobject_version INT DEFAULT NULL, depth INT DEFAULT 0 NOT NULL, is_hidden INT DEFAULT 0 NOT NULL, is_invisible INT DEFAULT 0 NOT NULL, main_node_id INT DEFAULT NULL, modified_subnode INT DEFAULT 0, parent_node_id INT DEFAULT 0 NOT NULL, path_identification_string TEXT DEFAULT NULL, path_string VARCHAR(255) DEFAULT '' NOT NULL, priority INT DEFAULT 0 NOT NULL, remote_id VARCHAR(100) DEFAULT '' NOT NULL, sort_field INT DEFAULT 1, sort_order INT DEFAULT 1, trashed INT DEFAULT 0 NOT NULL, PRIMARY KEY(node_id));
